package code;

import java.util.*;

class FuelMonitor25 {
    private double efficiencyThreshold;
    private List<String> consumptionLog;

    public FuelMonitor25(double efficiencyThreshold) {
        this.efficiencyThreshold = efficiencyThreshold;
        this.consumptionLog = new ArrayList<>();
    }

    public void recordTrip(double distance, double fuelUsed) {
        if (fuelUsed <= 0 || distance <= 0) {
            System.out.println("Invalid input: Distance and fuel consumption must be greater than zero.");
            return;
        }

        double efficiency = distance / fuelUsed; // km per liter

        String message = String.format("Distance: %.1f km | Fuel Used: %.2f L | Efficiency: %.2f km/L", 
                                       distance, fuelUsed, efficiency);
        if (efficiency < efficiencyThreshold) {
            message += " | WARNING: Low Efficiency! Consider improving driving habits.";
        }

        System.out.println(message);
        consumptionLog.add(message);
    }

    public void printConsumptionLog() {
        System.out.println("\nFuel Consumption Log:");
        for (String log : consumptionLog) {
            System.out.println(log);
        }
    }
}

